import{_ as s,a0 as l,w as d,s as i,I as o,x as t,a1 as r,A as p,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Docker 容器之間設置網絡 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Docker 容器之間設置網絡 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Docker 容器之間設置網絡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Docker 容器之間設置網絡 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150323 How to set up networking between Docker containers","title":"如何在 Docker 容器之間設置網絡","tag":"201506","desc":""},"relativePath":"201506/20150323 How to set up networking between Docker containers.md","filePath":"[post].md"}'),u={name:"201506/20150323 How to set up networking between Docker containers.md"};function w(m,e,v,f,k,c){const a=l("Link");return d(),i("div",null,[e[25]||(e[25]=o("h1",{id:"如何在-docker-容器之間設置網絡",tabindex:"-1"},[t("如何在 Docker 容器之間設置網絡 "),o("a",{class:"header-anchor",href:"#如何在-docker-容器之間設置網絡","aria-label":"Permalink to “如何在 Docker 容器之間設置網絡”"},"​")],-1)),e[26]||(e[26]=o("p",null,"你也許已經知道了，Docker 容器技術是現有的成熟虛擬化技術的一個替代方案。它被企業應用在越來越多的領域中，比如快速部署環境、簡化基礎設施的配置流程、多客户環境間的互相隔離等等。當你開始在真實的生產環境使用 Docker 容器去部署應用沙箱時，你可能需要用到多個容器部署一套複雜的多層應用系統，其中每個容器負責一個特定的功能（例如負載均衡、LAMP 棧、資料庫、UI 等）。",-1)),e[27]||(e[27]=o("p",null,"那麼問題來了：有多台宿主機，我們事先不知道會在哪台宿主機上創建容器，如果保證在這些宿主機上創建的容器們可以互相聯網？",-1)),o("p",null,[e[1]||(e[1]=t("聯網技術哪家強？開源方案找 ",-1)),r(a,{href:"https://github.com/zettio/weave"},{default:p(()=>[...e[0]||(e[0]=[t("weave",-1)])]),_:1}),e[2]||(e[2]=t("。這個工具可以為你省下不少煩惱。聽我的準沒錯，誰用誰知道。",-1))]),e[28]||(e[28]=n('<p>於是本教程的主題就變成了“<strong>如何使用 weave 在不同主機上的 Docker 容器之間設置網絡</strong>”。</p><h3 id="weave-是如何工作的" tabindex="-1">Weave 是如何工作的 <a class="header-anchor" href="#weave-是如何工作的" aria-label="Permalink to “Weave 是如何工作的”">​</a></h3><p><img src="https://farm8.staticflickr.com/7288/16662287067_27888684a7_b.jpg" alt=""></p><p>讓我們先來看看 weave 怎麼工作：先創建一個由多個 peer 組成的對等網絡，每個 peer 是一個虛擬路由器容器，叫做“weave 路由器”，它們分佈在不同的宿主機上。這個對等網絡的每個 peer 之間會維持一個 TCP 鏈接，用於互相交換拓撲信息，它們也會建立 UDP 鏈接用於容器間通信。一個 weave 路由器通過橋接技術連接到本宿主機上的其他容器。當處於不同宿主機上的兩個容器想要通信，一台宿主機上的 weave 路由器通過網橋截獲數據包，使用 UDP 協議封裝後發給另一台宿主機上的 weave 路由器。</p><p>每個 weave 路由器會刷新整個對等網絡的拓撲信息，可以稱作容器的 MAC 地址（如同交換機的 MAC 地址學習一樣獲取其他容器的 MAC 地址），因此它可以決定數據包的下一跳是往哪個容器的。weave 能讓兩個處於不同宿主機的容器進行通信，只要這兩台宿主機在 weave 拓撲結構內連到同一個 weave 路由器。另外，weave 路由器還能使用公鑰加密技術將 TCP 和 UDP 數據包進行加密。</p><h3 id="準備工作" tabindex="-1">準備工作 <a class="header-anchor" href="#準備工作" aria-label="Permalink to “準備工作”">​</a></h3>',6)),o("p",null,[e[6]||(e[6]=t("在使用 weave 之前，你需要在所有宿主機上安裝 ",-1)),r(a,{href:"http://xmodulo.com/recommend/dockerbook"},{default:p(()=>[...e[3]||(e[3]=[t("Docker",-1)])]),_:1}),e[7]||(e[7]=t(" 環境，參考",-1)),r(a,{href:"http://xmodulo.com/manage-linux-containers-docker-ubuntu.html"},{default:p(()=>[...e[4]||(e[4]=[t("這些",-1)])]),_:1}),r(a,{href:"http://xmodulo.com/docker-containers-centos-fedora.html"},{default:p(()=>[...e[5]||(e[5]=[t("教程",-1)])]),_:1}),e[8]||(e[8]=t("，在 Ubuntu 或 CentOS/Fedora 發行版中安裝 Docker。",-1))]),e[29]||(e[29]=n(`<p>Docker 環境部署完成後，使用下面的命令安裝 weave：</p><pre><code>$ wget https://github.com/zettio/weave/releases/download/latest_release/weave
$ chmod a+x weave
$ sudo cp weave /usr/local/bin 
</code></pre><p>注意你的 PATH 環境變量要包含 /usr/local/bin 這個路徑，請在 /etc/profile 文件中加入一行（LCTT 譯註：要使環境變量生效，你需要執行這個命令： source /etc/profile）：</p><pre><code>export PATH=&quot;$PATH:/usr/local/bin&quot;
</code></pre><p>在每台宿主機上重複上面的操作。</p><p>Weave 在 TCP 和 UDP 上都使用 6783 端口，如果你的系統開啓了防火牆，請確保這兩個端口不會被防火牆擋住。</p><h3 id="在每台宿主機上啓動-weave-路由器" tabindex="-1">在每台宿主機上啓動 Weave 路由器 <a class="header-anchor" href="#在每台宿主機上啓動-weave-路由器" aria-label="Permalink to “在每台宿主機上啓動 Weave 路由器”">​</a></h3><p>當你想要讓處於在不同宿主機上的容器能夠互相通信，第一步要做的就是在每台宿主機上啓動 weave 路由器。</p><p>第一台宿主機，運行下面的命令，就會創建並開啓一個 weave 路由器容器（LCTT 譯註：前面説過了，weave 路由器也是一個容器）：</p><pre><code>$ sudo weave launch 
</code></pre><p>第一次運行這個命令的時候，它會下載一個 weave 鏡像，這會花一些時間。下載完成後就會自動運行這個鏡像。成功啓動後，終端會輸出這個 weave 路由器的 ID 號。</p><p>下面的命令用於查看路由器狀態：</p><pre><code>$ sudo weave status 
</code></pre><p><img src="https://farm9.staticflickr.com/8632/16249607573_4514790cf5_c.jpg" alt=""></p><p>第一個 weave 路由器就緒了，目前為止整個 peer 對等網絡中只有一個 peer 成員。</p><p>你也可以使用 docker 的命令來查看 weave 路由器的狀態：</p><pre><code>$ docker ps 
</code></pre><p><img src="https://farm8.staticflickr.com/7655/16681964438_51d8b18809_c.jpg" alt=""></p><p>第二台宿主機部署步驟稍微有點不同，我們需要為這台宿主機的 weave 路由器指定第一台宿主機的 IP 地址，命令如下：</p><pre><code>$ sudo weave launch &lt;first-host-IP-address&gt; 
</code></pre><p>當你查看路由器狀態，你會看到兩個 peer 成員：當前宿主機和第一個宿主機。</p><p><img src="https://farm8.staticflickr.com/7608/16868571891_e66d4b8841_c.jpg" alt=""></p><p>當你開啓更多路由器，這個 peer 成員列表會更長。當你新開一個路由器時，要指定前一個宿主機的 IP 地址，請注意不是第一個宿主機的 IP 地址（LCTT 譯註：鏈狀結構）。</p><p>現在你已經有了一個 weave 網絡了，它由位於不同宿主機的 weave 路由器組成。</p><h3 id="把不同宿主機上的容器互聯起來" tabindex="-1">把不同宿主機上的容器互聯起來 <a class="header-anchor" href="#把不同宿主機上的容器互聯起來" aria-label="Permalink to “把不同宿主機上的容器互聯起來”">​</a></h3><p>接下來要做的就是在不同宿主機上開啓 Docker 容器，並使用虛擬網絡將它們互聯起來。</p><p>假設我們創建一個私有網絡 10.0.0.0/24 來互聯 Docker 容器，併為這些容器隨機分配 IP 地址。</p><p>如果你想新建一個能加入 weave 網絡的容器，你就需要使用 weave 命令來創建，而不是 docker 命令。原因是 weave 命令內部會調用 docker 命令來新建容器然後為它設置網絡。</p><p>下面的命令是在宿主機 hostA 上建立一個 Ubuntu 容器，然後將它放到 10.0.0.0/24 網絡中，分配的 IP 地址為 10.0.0.1：</p><pre><code>hostA:~$ sudo weave run 10.0.0.1/24 -t -i ubuntu 
</code></pre><p>成功運行後，終端會顯示出容器的 ID 號。你可以使用這個 ID 來訪問這個容器：</p><pre><code>hostA:~$ docker attach &lt;container-id&gt; 
</code></pre><p>在宿主機 hostB 上，也創建一個 Ubuntu 容器，IP 地址為 10.0.0.2：</p><pre><code>hostB:~$ sudo weave run 10.0.0.2/24 -t -i ubuntu 
</code></pre><p>訪問下這個容器的控制台：</p><pre><code>hostB:~$ docker attach &lt;container-id&gt; 
</code></pre><p>這兩個容器能夠互相 ping 通，你可以通過容器的控制台檢查一下。</p><p><img src="https://farm9.staticflickr.com/8566/16868571981_d73c8e401b_c.jpg" alt=""></p><p>如果你檢查一下每個容器的網絡配置，你會發現有一塊名為“ethwe”的網卡，你分配給容器的 IP 地址出現在它們那裏（比如這裏分別是 10.0.0.1 和 10.0.0.2）。</p><p><img src="https://farm8.staticflickr.com/7286/16681964648_013f9594b1_b.jpg" alt=""></p><h3 id="weave-的其他高級用法" tabindex="-1">Weave 的其他高級用法 <a class="header-anchor" href="#weave-的其他高級用法" aria-label="Permalink to “Weave 的其他高級用法”">​</a></h3><p>weave 提供了一些非常巧妙的特性，我在這裏作下簡單的介紹。</p><h4 id="應用分離" tabindex="-1">應用分離 <a class="header-anchor" href="#應用分離" aria-label="Permalink to “應用分離”">​</a></h4><p>使用 weave，你可以創建多個虛擬網絡，併為每個網絡設置不同的應用。比如你可以為一羣容器創建 10.0.0.0/24 網絡，為另一羣容器創建 10.10.0.0/24 網絡，weave 會自動幫你維護這些網絡，並將這兩個網絡互相隔離。另外，你可以靈活地將一個容器從一個網絡移到另一個網絡而不需要重啓容器。舉個例子：</p><p>首先開啓一個容器，運行在 10.0.0.0/24 網絡上：</p><pre><code>$ sudo weave run 10.0.0.2/24 -t -i ubuntu
</code></pre><p>然後讓它脱離這個網絡：</p><pre><code>$ sudo weave detach 10.0.0.2/24 &lt;container-id&gt;
</code></pre><p>最後將它加入到 10.10.0.0/24 網絡中：</p><pre><code>$ sudo weave attach 10.10.0.2/24 &lt;container-id&gt; 
</code></pre><p><img src="https://farm8.staticflickr.com/7639/16247212144_c31a49714d_c.jpg" alt=""></p><p>現在這個容器可以與 10.10.0.0/24 網絡上的其它容器進行通信了。這在當你創建一個容器而網絡信息還不確定時就很有幫助了。</p><h4 id="將-weave-網絡與宿主機網絡整合起來" tabindex="-1">將 weave 網絡與宿主機網絡整合起來 <a class="header-anchor" href="#將-weave-網絡與宿主機網絡整合起來" aria-label="Permalink to “將 weave 網絡與宿主機網絡整合起來”">​</a></h4><p>有時候你想讓虛擬網絡中的容器能訪問物理主機的網絡。或者相反，宿主機需要訪問容器。為滿足這個功能，weave 允許虛擬網絡與宿主機網絡整合。</p><p>舉個例子，在宿主機 hostA 上一個容器運行在 10.0.0.0/24 中，運行使用下面的命令：</p><pre><code>hostA:~$ sudo weave expose 10.0.0.100/24 
</code></pre><p>這個命令把 IP 地址 10.0.0.100 分配給宿主機 hostA，這樣一來宿主機 hostA 也連到了 10.0.0.0/24 網絡上了。顯然，你在為宿主機選擇 IP 地址的時候，需要選一個沒有被其他容器使用的地址。</p><p>現在 hostA 就可以訪問 10.0.0.0/24 上的所有容器了，不管這些容器是否位於 hostA 上。好巧妙的設定啊，32 個贊！</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>`,59)),o("p",null,[e[10]||(e[10]=t("如你所見，weave 是一個很有用的 docker 網絡配置工具。這個教程只是它",-1)),r(a,{href:"http://zettio.github.io/weave/features.html"},{default:p(()=>[...e[9]||(e[9]=[t("強悍功能",-1)])]),_:1}),e[11]||(e[11]=t("的冰山一角。如果你想進一步玩玩，你可以試試它的以下功能：多跳路由功能，這個在 multi-cloud 環境（LCTT 譯註：多雲，企業使用多個不同的雲服務提供商的產品，比如 IaaS 和 SaaS，來承載不同的業務）下還是很有用的；動態重路由功能是一個很巧妙的容錯技術；或者它的分佈式 DNS 服務，它允許你為你的容器命名。如果你決定使用這個好東西，歡迎分享你的使用心得。",-1))]),e[30]||(e[30]=o("hr",null,null,-1)),o("p",null,[e[13]||(e[13]=t("via: ",-1)),r(a,{href:"http://xmodulo.com/networking-between-docker-containers.html"},{default:p(()=>[...e[12]||(e[12]=[t("http://xmodulo.com/networking-between-docker-containers.html",-1)])]),_:1})]),o("p",null,[e[17]||(e[17]=t("作者：",-1)),r(a,{href:"http://xmodulo.com/author/nanni"},{default:p(()=>[...e[14]||(e[14]=[t("Dan Nanni",-1)])]),_:1}),e[18]||(e[18]=t(" 譯者：",-1)),r(a,{href:"https://github.com/bazz2"},{default:p(()=>[...e[15]||(e[15]=[t("bazz2",-1)])]),_:1}),e[19]||(e[19]=t(" 校對：",-1)),r(a,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:p(()=>[...e[16]||(e[16]=[t("校對者ID",-1)])]),_:1})]),o("p",null,[e[22]||(e[22]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[20]||(e[20]=[t("LCTT",-1)])]),_:1}),e[23]||(e[23]=t(" 原創翻譯，",-1)),r(a,{href:"http://linux.cn/"},{default:p(()=>[...e[21]||(e[21]=[t("Linux中國",-1)])]),_:1}),e[24]||(e[24]=t(" 榮譽推出",-1))])])}const g=s(u,[["render",w]]);export{T as __pageData,g as default};
